/**
 * Branch Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. The query object stays local and is marked as such.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** The wire row on GET/POST/PATCH `/branches` (`BranchResponseDto`). */
type BranchWire = Schemas["BranchResponseDto"]

/**
 * Fields the wire sends but `toBranch` (`lib/api/branches.ts`) has never
 * mapped onto the dashboard object. Nothing in the dashboard reads them, so
 * keeping them out of the type is what stops them from being used and what
 * keeps every branch payload byte-identical to before this change.
 */
type BranchFieldsNotMapped = "city" | "country" | "latitude" | "longitude"

/**
 * Dashboard-facing branch.
 *
 * `nameEn` is nullable on the wire (the column is optional) but every branch
 * surface has always rendered it as a string, so `toBranch` normalises `null`
 * to `""` once. Together with `BranchFieldsNotMapped`, those are the only
 * documented deviations from the wire row.
 */
export type Branch = Omit<BranchWire, "nameEn" | BranchFieldsNotMapped> & {
  nameEn: string
}

/** The link row returned when an employee is assigned (`POST .../employees`). */
export type BranchEmployeeAssignment = Schemas["BranchEmployeeAssignmentResponseDto"]

/* ─── Query (local; not a response shape) ─── */

export interface BranchListQuery extends PaginatedQuery {
  search?: string
  isActive?: boolean
}
